import { parseBackendError, type AppError } from '@ble-frontend/domain-types';
import { OpenAPI } from './generated/core/OpenAPI';

export class ApiRequestException extends Error {
  readonly appError: AppError;

  constructor(appError: AppError) {
    super(`[${appError.code}] ${appError.message}`);
    this.name = 'ApiRequestException';
    this.appError = appError;
  }
}

/**
 * Base HTTP client wrapper providing pipeline execution and typed convenience methods.
 * Endpoints generated by @hey-api live in ./generated/services.gen.ts.
 */
export class ApiClient {
  private baseURL: string;

  constructor(baseURL: string = '/api/v1') {
    this.baseURL = baseURL;
  }

  setBaseURL(url: string): void {
    this.baseURL = url;
    OpenAPI.BASE = url;
  }

  getBaseURL(): string {
    return this.baseURL;
  }

  async request<T>(path: string, options: RequestInit = {}): Promise<T> {
    const inputHeaders = options.headers as HeadersInit | undefined;
    const headers = new Headers(inputHeaders);

    if (!headers.has('Content-Type') && options.body && typeof options.body === 'string') {
      headers.set('Content-Type', 'application/json');
    }

    let request: RequestInit = {
      ...options,
      headers,
    };

    // Execute registered request interceptors
    for (const fn of OpenAPI.interceptors.request._fns) {
      request = await fn(request);
    }

    const fullUrl = path.startsWith('http')
      ? path
      : `${this.baseURL.replace(/\/+$/, '')}/${path.replace(/^\/+/, '')}`;

    let response: Response;
    try {
      response = await fetch(fullUrl, request);
    } catch (networkError) {
      const appErr = parseBackendError({
        code: 'ERR_NETWORK',
        message: networkError instanceof Error ? networkError.message : 'Network error occurred',
        request,
      });
      throw new ApiRequestException(appErr);
    }

    // Execute registered response interceptors
    for (const fn of OpenAPI.interceptors.response._fns) {
      response = await fn(response);
    }

    if (!response.ok) {
      let body: unknown = null;
      try {
        body = await response.json();
      } catch {
        try {
          body = await response.text();
        } catch {}
      }

      const appError = parseBackendError({
        response: {
          status: response.status,
          statusText: response.statusText,
          data: body,
          headers: {
            'x-trace-id': response.headers.get('x-trace-id') ?? undefined,
          },
        },
      });

      throw new ApiRequestException(appError);
    }

    if (response.status === 204) {
      return undefined as unknown as T;
    }

    return (await response.json()) as T;
  }

  get<T>(path: string, options: RequestInit = {}): Promise<T> {
    return this.request<T>(path, { ...options, method: 'GET' });
  }

  post<T>(path: string, body?: unknown, options: RequestInit = {}): Promise<T> {
    return this.request<T>(path, {
      ...options,
      method: 'POST',
      body:
        body !== undefined ? (typeof body === 'string' ? body : JSON.stringify(body)) : undefined,
    });
  }

  put<T>(path: string, body?: unknown, options: RequestInit = {}): Promise<T> {
    return this.request<T>(path, {
      ...options,
      method: 'PUT',
      body:
        body !== undefined ? (typeof body === 'string' ? body : JSON.stringify(body)) : undefined,
    });
  }

  delete<T>(path: string, options: RequestInit = {}): Promise<T> {
    return this.request<T>(path, { ...options, method: 'DELETE' });
  }

  patch<T>(path: string, body?: unknown, options: RequestInit = {}): Promise<T> {
    return this.request<T>(path, {
      ...options,
      method: 'PATCH',
      body:
        body !== undefined ? (typeof body === 'string' ? body : JSON.stringify(body)) : undefined,
    });
  }
}

export const apiClient = new ApiClient();
